-- purge returned: Delete the returned loans
-- Changes exactly 4 Loan records of table loans: sets is_deleted to true, where status == "returned".
-- Dry run: psql -v ON_ERROR_STOP=1 -v last_modified_by_user_id=... -v last_modified_by_user_nameid=... -f purge-returned.sql
-- Apply: the same with -v apply=true. Without it every check runs against the data and the change is rolled back.
\set ON_ERROR_STOP on
\set QUIET on
\if :{?apply}
\else
\set apply false
\endif
\if :{?last_modified_by_user_id}
\else
DO $script$ BEGIN RAISE EXCEPTION 'purge-returned.sql: the variable last_modified_by_user_id is not set; give it as psql -v last_modified_by_user_id=<last_modified_by_user_id> (VARCHAR(255))'; END $script$;
\endif
\if :{?last_modified_by_user_nameid}
\else
DO $script$ BEGIN RAISE EXCEPTION 'purge-returned.sql: the variable last_modified_by_user_nameid is not set; give it as psql -v last_modified_by_user_nameid=<last_modified_by_user_nameid> (VARCHAR(255))'; END $script$;
\endif
BEGIN;
SET LOCAL specarch.apply = :'apply';
SET LOCAL specarch.last_modified_by_user_id = :'last_modified_by_user_id';
SET LOCAL specarch.last_modified_by_user_nameid = :'last_modified_by_user_nameid';
DO $script$
DECLARE
  found bigint;
  changed bigint;
BEGIN
  -- 1. Precondition: exactly 4 Loan records to change, locked until the end.
  SELECT count(*) INTO found FROM (SELECT 1 FROM loans WHERE (status = 'returned')
    AND is_deleted = false FOR UPDATE) AS records;
  IF found <> 4 THEN
    RAISE EXCEPTION 'command purge returned: % Loan records hold status == "returned", not deleted, and the change expects exactly 4; nothing was changed', found;
  END IF;
  -- 2. The change, under the same condition.
  UPDATE loans
  SET is_deleted = true,
      last_modified_at = now(),
      last_modified_by_user_id = current_setting('specarch.last_modified_by_user_id', true)::VARCHAR,
      last_modified_by_user_nameid = current_setting('specarch.last_modified_by_user_nameid', true)::VARCHAR
  WHERE (status = 'returned')
    AND is_deleted = false;
  GET DIAGNOSTICS changed = ROW_COUNT;
  -- 3. Postcondition: the exact count.
  IF changed <> 4 THEN
    RAISE EXCEPTION 'command purge returned: the change wrote % Loan records, and exactly 4 was expected; another writer may have changed them after they were counted; nothing was changed', changed;
  END IF;
  -- 4. Dry run unless apply is true.
  IF current_setting('specarch.apply')::boolean THEN
    RAISE NOTICE 'command purge returned: 4 Loan records changed; committing';
  ELSE
    RAISE NOTICE 'command purge returned: dry run: 4 Loan records would change, and every check passed; rolling back. Run it again with -v apply=true to make the change';
  END IF;
END
$script$;
\if :apply
